"""Integration test for LSP navigation — NO MOCKS.

See lsp/docs/DESIGN_LSP_MCP_INTEGRATION.md §6.2.

What is genuinely exercised:
* a real Serena starts as a stdio MCP server through the EXISTING
  ``ExternalMCPClientPool`` (we test the production path, not a
  hand-rolled client);
* the mcp.json entry generated by our code actually yields a working
  server;
* ``find_symbol`` finds a class in the fixture, ``find_referencing_symbols``
  finds its consumer — i.e. the target UX "one call → precise answer"
  works;
* teardown is correct: no child process is left as an orphan.

"Integration tests must not hang" policy: a hard budget on
EVERYTHING, including pool startup; on
timeout — fail loud (NOT skip); event-driven waiting via
``asyncio.wait_for``; teardown guaranteed in ``finally``.

Skip only if Serena is not installed — except in
``DEEP_WORKER_REQUIRE_INTEGRATION=1`` mode, where a missing tool must
fail the build.
"""
from __future__ import annotations

import asyncio
import json
import os
import shutil
import subprocess
import sys
from pathlib import Path

import pytest

from deep_worker_cli.external_mcp.pool import ExternalMCPClientPool
from deep_worker_cli.lsp.serena_config import (
    SERENA_COMMAND,
    SERENA_SERVER_NAME,
    build_serena_mcp_entry,
)

pytestmark = pytest.mark.integration

# Measured on serena-agent 1.6.1 (§11 of the design): startup ~3.6 s,
# first find_symbol ~1 s. The budgets below are generous but finite.
_POOL_START_BUDGET_SEC = 40.0
_TOOL_CALL_BUDGET_SEC = 30.0
_TOTAL_BUDGET_SEC = 60.0

_FIND_SYMBOL = f"{SERENA_SERVER_NAME}__find_symbol"
_FIND_REFS = f"{SERENA_SERVER_NAME}__find_referencing_symbols"


def _require_serena() -> None:
    if shutil.which(SERENA_COMMAND):
        return
    msg = (
        f"{SERENA_COMMAND!r} not found in PATH; install with "
        f"'uv tool install -p 3.13 serena-agent'"
    )
    if os.environ.get("DEEP_WORKER_REQUIRE_INTEGRATION") == "1":
        pytest.fail(msg)
    pytest.skip(msg)


def _make_fixture_project(root: Path) -> None:
    """A tiny Python project with a symbol and its consumer."""
    pkg = root / "pkg"
    pkg.mkdir(parents=True)
    (pkg / "__init__.py").write_text("", encoding="utf-8")
    (pkg / "mod.py").write_text(
        "class LspProbeTarget:\n"
        "    def compute(self) -> int:\n"
        "        return 42\n",
        encoding="utf-8",
    )
    (pkg / "user.py").write_text(
        "from pkg.mod import LspProbeTarget\n"
        "\n"
        "\n"
        "def call_it() -> int:\n"
        "    return LspProbeTarget().compute()\n",
        encoding="utf-8",
    )


def _write_mcp_config(cfg: Path, workspace: Path) -> None:
    cfg.parent.mkdir(parents=True, exist_ok=True)
    cfg.write_text(
        json.dumps(
            {
                "mcpServers": {
                    SERENA_SERVER_NAME: build_serena_mcp_entry(
                        workspace_root=workspace
                    )
                }
            }
        ),
        encoding="utf-8",
    )


def _serena_child_pids() -> set[int]:
    """PIDs of the LIVE Serena descendants of the current process.

    Deliberately filter by command line instead of taking all descendants:
    the measurement itself runs through ``ps``, and this helper process
    would otherwise land in the sample and look like a "leak" (verified —
    that is exactly what happened on the first run).

    Zombies (STAT ``Z``) are also excluded: a reaped process holds no
    resources, and we only care about genuinely live orphans.
    """
    try:
        out = subprocess.run(
            ["ps", "-o", "pid=,stat=,args=", "--ppid", str(os.getpid())],
            capture_output=True, text=True, timeout=10, check=False,
        ).stdout
    except (OSError, subprocess.SubprocessError):  # pragma: no cover
        return set()

    pids: set[int] = set()
    for line in out.splitlines():
        parts = line.split(maxsplit=2)
        if len(parts) < 3:
            continue
        pid_s, stat_s, cmd = parts
        if not pid_s.isdigit() or stat_s.startswith("Z"):
            continue
        if SERENA_COMMAND in cmd or "start-mcp-server" in cmd:
            pids.add(int(pid_s))
    return pids


async def _call_tool(tools: list, name: str, **kwargs) -> str:
    tool = next((t for t in tools if t.name == name), None)
    assert tool is not None, f"tool {name!r} missing; got {[t.name for t in tools]}"
    return await asyncio.wait_for(tool._arun(**kwargs), timeout=_TOOL_CALL_BUDGET_SEC)


@pytest.mark.asyncio
async def test_serena_lsp_navigation_end_to_end(tmp_path: Path) -> None:
    _require_serena()

    workspace = tmp_path / "fixture"
    _make_fixture_project(workspace)
    cfg = tmp_path / ".deepagents" / "mcp.json"
    _write_mcp_config(cfg, workspace)

    pids_before = _serena_child_pids()

    async def _scenario() -> None:
        # Pool startup is ALSO under a timeout: a hung Serena would otherwise
        # hang CI (the pool itself has no budget — see §7.1 of the design).
        pool = await asyncio.wait_for(
            ExternalMCPClientPool.create(
                user_path=cfg,
                project_path=None,
                agent_path=None,
                cli_configs=[],
                cli_servers=[],
            ),
            timeout=_POOL_START_BUDGET_SEC,
        )
        try:
            names = [t.name for t in pool.tools]
            assert names, "Serena started but exposed no tools"

            # Names are mangled (`serena.find_symbol` → `serena__…`), exactly
            # as the agent will see them. This is also the requirement for
            # the prompt.
            assert _FIND_SYMBOL in names, names

            # By design the server is marked auto_approve → its
            # tools do not require HITL.
            assert _FIND_SYMBOL in pool.auto_approved_tool_names

            # 1) Go to definition / find symbol by name — a single call.
            found = await _call_tool(
                pool.tools, _FIND_SYMBOL, name_path="LspProbeTarget"
            )
            assert "LspProbeTarget" in found, found
            assert "pkg/mod.py" in found, found

            # 2) Show usages — must point at the consumer file.
            if _FIND_REFS in names:
                refs = await _call_tool(
                    pool.tools, _FIND_REFS,
                    name_path="LspProbeTarget", relative_path="pkg/mod.py",
                )
                assert "user.py" in refs, refs
        finally:
            await pool.stop()

    try:
        await asyncio.wait_for(_scenario(), timeout=_TOTAL_BUDGET_SEC)
    except TimeoutError:
        pytest.fail(
            f"LSP integration exceeded the {_TOTAL_BUDGET_SEC}s budget — "
            "treat as a real failure (hang), not a flake"
        )

    # Teardown: no Serena orphans must remain.
    leaked = _serena_child_pids() - pids_before
    assert not leaked, f"serena process(es) leaked after pool.stop(): {leaked}"


@pytest.mark.asyncio
async def test_generated_config_is_what_pool_consumes(tmp_path: Path) -> None:
    """Our generator → existing loader → real start.

    A separate lightweight test of the same contract in case the main
    scenario is skipped for lack of the binary.
    """
    workspace = tmp_path / "ws"
    workspace.mkdir()
    entry = build_serena_mcp_entry(workspace_root=workspace)

    assert entry["command"] == SERENA_COMMAND
    assert str(workspace.resolve()) in entry["args"]
    assert sys.executable  # sanity: the test runs in a real interpreter
